CREATE OR ALTER PROCEDURE [dbo].[uspAttendanceEvent_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @EmployeeId UNIQUEIDENTIFIER = NULL
	, @ShiftAssignmentId UNIQUEIDENTIFIER = NULL
	, @EventType NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[EmployeeId]
			, t.[ShiftAssignmentId]
			, t.[EventType]
			, t.[EventAt]
			, t.[Latitude]
			, t.[Longitude]
			, t.[DistanceMeters]
			, t.[IsValid]
			, t.[SourceChannel]
			, t.[ExternalEventId]
			, t.[Note]
			, t.[CreatedDate]
		FROM [dbo].[AttendanceEvent] AS t
		
		WHERE 1 = 1
			AND (@EmployeeId IS NULL OR t.[EmployeeId] = @EmployeeId)
			AND (@ShiftAssignmentId IS NULL OR t.[ShiftAssignmentId] = @ShiftAssignmentId)
			AND (ISNULL(@EventType, '') = '' OR t.[EventType] = @EventType)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'employeeId' THEN r.[EmployeeId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'employeeId' THEN r.[EmployeeId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'shiftAssignmentId' THEN r.[ShiftAssignmentId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'shiftAssignmentId' THEN r.[ShiftAssignmentId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'eventType' THEN r.[EventType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'eventType' THEN r.[EventType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'eventAt' THEN r.[EventAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'eventAt' THEN r.[EventAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'latitude' THEN r.[Latitude] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'latitude' THEN r.[Latitude] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'longitude' THEN r.[Longitude] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'longitude' THEN r.[Longitude] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'distanceMeters' THEN r.[DistanceMeters] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'distanceMeters' THEN r.[DistanceMeters] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'isValid' THEN r.[IsValid] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'isValid' THEN r.[IsValid] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'sourceChannel' THEN r.[SourceChannel] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'sourceChannel' THEN r.[SourceChannel] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'externalEventId' THEN r.[ExternalEventId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'externalEventId' THEN r.[ExternalEventId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
